// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    PoCGame c;

    function setUp() public { c = new PoCGame(address(this), 0); }

    function testFuzz_property(bool retFromTokenAddress, uint256 tokens) public {
        Token tAtTokenAddress = new Token();
        Token tAtTokenOwner = new Token();
        tAtTokenAddress.setReturn(retFromTokenAddress);
        tAtTokenOwner.setReturn(!retFromTokenAddress);

        // The reference must relay the return value of the token AT tokenAddress
        // (tAtTokenAddress) for a transfer to tokenOwner (tAtTokenOwner).
        try c.transferAnyERC20Token(address(tAtTokenAddress), address(tAtTokenOwner), tokens) returns (bool success) {
            assertTrue(success == retFromTokenAddress);
        } catch {
            assertTrue(false);
        }
    }
}

contract Token {
    bool private ret;

    function setReturn(bool r) public { ret = r; }

    function transfer(address to, uint256 tokens) public returns (bool success) {
        return ret;
    }
}
